using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;
namespace Folha {
static class Tests {
 sealed class MemoryRemote:Remote {
  public readonly List<Dictionary<string,object>> files=new List<Dictionary<string,object>>();readonly Dictionary<string,byte[]> bytes=new Dictionary<string,byte[]>();public Action OnDownload;public int blobs;
  public void LoadWire(string dir){var index=J.Parse(File.ReadAllText(Path.Combine(dir,"index.json")));foreach(var o in J.List(index["files"])){var f=J.Obj(o);var id=J.S(f,"id");files.Add(f);bytes[id]=File.ReadAllBytes(Path.Combine(dir,id));}}
  public void SaveWire(string dir){Directory.CreateDirectory(dir);foreach(var f in files)File.WriteAllBytes(Path.Combine(dir,J.S(f,"id")),bytes[J.S(f,"id")]);File.WriteAllText(Path.Combine(dir,"index.json"),J.Encode(new{files=files}));}
  public List<Dictionary<string,object>> Files(){return files.Select(x=>J.Parse(J.Encode(x))).ToList();}
  public string Upload(string name,string file,Dictionary<string,object> props){var id=J.Id();bytes[id]=File.ReadAllBytes(file);files.Add(new Dictionary<string,object>{{"id",id},{"name",name},{"appProperties",props}});if(J.S(props,"kind")=="blob")blobs++;return id;}
  public void Download(string id,string dest,long limit){if(bytes[id].Length>limit)throw new Exception("limit");File.WriteAllBytes(dest,bytes[id]);if(OnDownload!=null){var a=OnDownload;OnDownload=null;a();}}
 }
 static void Assert(bool v,string message){if(!v)throw new Exception(message);}
 public static void Run(){var root=Path.Combine(Path.GetTempPath(),"Folha-tests-"+J.Id());Directory.CreateDirectory(root);var log=new List<string>();try{GlyphChecks(root);log.Add("PASS Japanese contours survive store/backup and remain immutable through Windows text edits");VersionChecks(root);log.Add("PASS local versions bounded, recover as a separate copy with original assets");TrashSync(root);log.Add("PASS trash deletion and restoration propagate without resurrection or loss of PDF/ink");TextEdits();log.Add("PASS desktop typed-text edits preserve tablet ink and images; drawing edits rejected");var a=new Store(Path.Combine(root,"a"));var b=new Store(Path.Combine(root,"b"));var remote=new MemoryRemote();Func<string> closed=()=>"";var doc=a.Create("Português — matemática","lines");var id=J.S(doc,"id");doc["pdf"]=true;File.WriteAllText(Path.Combine(a.Dir(id),"source.pdf"),"%PDF-test-original");a.Write(doc);new SyncEngine(a,remote,"account-A",closed).Run();new SyncEngine(b,remote,"account-A",closed).Run();Assert(J.S(b.Read(id),"name")==J.S(doc,"name"),"First transfer lost metadata");Assert(remote.blobs==1,"Original PDF uploaded more than once");log.Add("PASS initial transfer and PDF integrity");
 var da=a.Read(id);da["name"]="Edição no PC";a.Write(da);var db=b.Read(id);db["folder"]="Edição no tablet";b.Write(db);new SyncEngine(a,remote,"account-A",closed).Run();new SyncEngine(b,remote,"account-A",closed).Run();new SyncEngine(a,remote,"account-A",closed).Run();var all=a.Library().Select(x=>a.Read(J.S(J.Obj(x),"id"))).ToList();Assert(all.Any(d=>J.S(d,"name").StartsWith("Edição no PC")),"PC edit lost");Assert(all.Any(d=>J.S(d,"folder")=="Edição no tablet"),"Tablet edit lost");Assert(all.Count==2,"Conflict did not produce exactly two notebooks");Assert(remote.blobs==1,"An annotation resent the original PDF");log.Add("PASS concurrent offline edits preserved as conflict copy");
 var count=remote.files.Count;new SyncEngine(a,remote,"account-A",closed).Run();new SyncEngine(b,remote,"account-A",closed).Run();new SyncEngine(a,remote,"account-A",closed).Run();Assert(remote.files.Count==count,"Sync not idempotent");log.Add("PASS repeated synchronization is idempotent");
 var before=b.Read(id);before["updated"]=J.Now()+100;before["revision"]=J.Id();before["lastPage"]=0;before["lastOpened"]=J.Now();b.Write(before);new SyncEngine(b,remote,"account-A",closed).Run();Assert(remote.files.Count==count,"Opening a document created a remote revision");log.Add("PASS volatile UI metadata does not trigger uploads");
 da=a.Read(id);da["name"]="Atualização remota";a.Write(da);new SyncEngine(a,remote,"account-A",closed).Run();var oldName=J.S(b.Read(id),"name");new SyncEngine(b,remote,"account-A",()=>id).Run();Assert(J.S(b.Read(id),"name")==oldName,"Open notebook was overwritten");new SyncEngine(b,remote,"account-A",closed).Run();Assert(J.S(b.Read(id),"name")=="Atualização remota","Closed notebook did not receive update");log.Add("PASS open notebook protected; update applied after close");
 var c=new Store(Path.Combine(root,"c"));new SyncEngine(c,remote,"account-B",closed).Run();Assert(c.Library().Length>=2,"Fresh device could not read revisions");log.Add("PASS independent sync-state namespace");
 var backup=Path.Combine(root,"backup.folha");a.Backup(id,backup);var copied=b.ImportBackup(backup);Assert(copied!=id&&J.S(b.Read(copied),"originId")==id,"Backup restore overwrote notebook");log.Add("PASS editable backup restores duplicate as a copy");
 var invalid=J.Parse(J.Encode(a.Read(id)));invalid["id"]="../../outside";bool rejected=false;try{a.Write(invalid);}catch{rejected=true;}Assert(rejected,"Path traversal accepted");rejected=false;try{a.DataFile(id,"../account.bin");}catch{rejected=true;}Assert(rejected,"Data route traversal accepted");log.Add("PASS document and resource path validation");
 StudyPaperChecks(root);log.Add("PASS ten study notebook types survive Windows store, backup and synchronized transfer with typed text");
 var arguments=Environment.GetCommandLineArgs();var wireIndex=Array.IndexOf(arguments,"--wire-fixture");if(wireIndex>=0){var cross=new MemoryRemote();cross.LoadWire(arguments[wireIndex+1]);var pc=new Store(Path.Combine(root,"interop"));new SyncEngine(pc,cross,"interop-account",closed).Run();Assert(pc.Library().Length==2,"Windows could not import Java wire revisions");var transferred=pc.Read("12345678-1234-1234-1234-123456789abc");Assert(J.S(transferred,"paper")=="genko400"&&Convert.ToBoolean(transferred["favorite"])&&J.S(transferred,"cover")=="blue","Japanese metadata lost");Assert(J.S(transferred,"name")=="Nova edição","Java Unicode metadata lost");var originalGlyph=J.List(J.Obj(transferred["pages"])["0"]).First();Assert(J.S(J.Obj(originalGlyph),"text")=="日"&&J.S(J.Obj(originalGlyph),"glyph").Length>0,"Java glyph lost");transferred["folder"]="Windows roundtrip";J.Obj(transferred["pages"])["0"]=new object[]{new{id=J.Id(),kind="ink",color=-14271438,width=2.5,marker=false,points=new[]{new[]{40d,60d,.25d},new[]{80d,100d,1.2d}}},originalGlyph};transferred=J.Parse(J.Encode(transferred));pc.Write(transferred);new SyncEngine(pc,cross,"interop-account",closed).Run();cross.SaveWire(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"test-wire"));log.Add("PASS real Java wire revisions imported, edited, exported by Windows");}
 File.WriteAllLines(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"test-results.txt"),log);Console.WriteLine(string.Join("\n",log));
 }catch(Exception e){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"test-results.txt"),string.Join("\n",log)+"\nFAIL "+e);throw;}finally{var full=Path.GetFullPath(root);if(full.StartsWith(Path.GetFullPath(Path.GetTempPath()),StringComparison.OrdinalIgnoreCase)&&Path.GetFileName(full).StartsWith("Folha-tests-"))Directory.Delete(full,true);}}
 static void StudyPaperChecks(string root){
 var a=new Store(Path.Combine(root,"study-a"));var b=new Store(Path.Combine(root,"study-b"));var remote=new MemoryRemote();var types=new[]{"cornell","errors","exercises","vocabulary","kanji-study","grammar","review","summary","planner","translation"};
 foreach(var type in types){var d=a.Create(type,type);d["cover"]="rose";DesktopEdits.Apply(d,new Dictionary<string,object>{{"op","append"},{"page",0},{"stroke",new Dictionary<string,object>{{"id",J.Id()},{"kind","text"},{"text","Minha anotação"},{"fontSize",18},{"x",60},{"y",150},{"boxW",200},{"boxH",50},{"color",-14271438},{"points",new object[0]}}}});a.Write(d);var id=J.S(d,"id");var backup=Path.Combine(root,type+".folha");a.Backup(id,backup);var restored=b.Read(b.ImportBackup(backup));Assert(J.S(restored,"paper")==type&&J.S(restored,"cover")=="rose"&&J.S(J.Obj(J.List(J.Obj(restored["pages"])["0"]).First()),"text")=="Minha anotação","Study backup lost metadata/text: "+type);}
 new SyncEngine(a,remote,"study-account",()=>"").Run();new SyncEngine(b,remote,"study-account",()=>"").Run();foreach(var type in types)Assert(b.Library().Select(x=>J.Obj(x)).Any(d=>J.S(d,"paper")==type&&J.S(d,"originId")==""),"Study transfer failed "+type);
 }
 static void GlyphChecks(string root){var store=new Store(Path.Combine(root,"glyph"));var d=store.Create("日本語","kanji");var glyph=J.Parse("{\"kind\":\"ink\",\"pen\":\"glyph\",\"color\":-14271438,\"width\":1,\"marker\":false,\"points\":[],\"text\":\"日\",\"glyph\":\"0,0 1000,0 1000,1000 0,1000;200,200 200,800 800,800 800,200\",\"x\":50,\"y\":60,\"boxW\":100,\"boxH\":100}");glyph["id"]=J.Id();J.Obj(d["pages"])["0"]=new object[]{glyph};store.Write(d);var id=J.S(d,"id");var before=J.Encode(J.Obj(J.List(J.Obj(store.Read(id)["pages"])["0"]).First()));var backup=Path.Combine(root,"glyph.folha");store.Backup(id,backup);var copy=store.Read(store.ImportBackup(backup));Assert(J.Encode(J.Obj(J.List(J.Obj(copy["pages"])["0"]).First()))==before,"Glyph backup lost contours");bool rejected=false;try{DesktopEdits.Apply(d,new Dictionary<string,object>{{"op","page"},{"page",0},{"strokes",new object[0]}});}catch{rejected=true;}Assert(rejected,"Windows erased regular character");var invalid=J.Parse(J.Encode(glyph));invalid["glyph"]="0,0 1001,0 0,1000";rejected=false;try{Glyphs.Validate(invalid);}catch{rejected=true;}Assert(rejected,"Out-of-bounds contour accepted");var args=Environment.GetCommandLineArgs();var index=Array.IndexOf(args,"--glyph-fixture");if(index>=0){var native=J.Parse(File.ReadAllText(args[index+1]));Store.Validate(native);store.Write(native);var restored=store.Read(J.S(native,"id"));Assert(J.Encode(restored["pages"])==J.Encode(native["pages"]),"Real Android glyphs not retained");}}
 static void VersionChecks(string root){var store=new Store(Path.Combine(root,"versions"));var d=store.Create("Original","genko400");var id=J.S(d,"id");d["favorite"]=true;d["cover"]="blue";d["pdf"]=true;File.WriteAllText(store.DataFile(id,"source.pdf"),"%PDF-test");store.Write(d);Versions.Save(store,d,true);d["name"]="Changed";store.Write(d);Assert(Versions.List(store,id).Length>0,"No recovery point");for(int i=0;i<15;i++)Versions.Save(store,d,true);Assert(Versions.List(store,id).Length==12,"Recovery points not bounded");var first=J.Parse(J.Encode(Versions.List(store,id)[0]));var copy=Versions.Restore(store,id,J.S(first,"key"));Assert(copy!=id&&J.S(store.Read(id),"name")=="Changed","Recovery overwrote original");Assert(J.S(store.Read(copy),"paper")=="genko400"&&J.S(store.Read(copy),"cover")=="blue","Recovery lost new metadata");Assert(File.ReadAllText(store.DataFile(copy,"source.pdf"))=="%PDF-test","Recovery lost PDF");var current=store.Read(id);var fingerprint=J.Fingerprint(current);current["lastOpened"]=J.Now();Assert(J.Fingerprint(current)==fingerprint,"Recents created a sync change");}
 static void TrashSync(string root){var a=new Store(Path.Combine(root,"trash-a"));var b=new Store(Path.Combine(root,"trash-b"));var r=new MemoryRemote();Func<string> closed=()=>"";var d=a.Create("Livro","blank");var id=J.S(d,"id");d["pdf"]=true;File.WriteAllText(a.DataFile(id,"source.pdf"),"%PDF-original");a.Write(d);new SyncEngine(a,r,"trash-account",closed).Run();new SyncEngine(b,r,"trash-account",closed).Run();a.Trash(id,true);Assert(a.Library().Length==0&&a.Library(true).Length==1,"Trash visibility failed");new SyncEngine(a,r,"trash-account",closed).Run();new SyncEngine(b,r,"trash-account",closed).Run();Assert(Store.IsDeleted(b.Read(id))&&b.Library().Length==0,"Deletion did not propagate");var count=r.files.Count;new SyncEngine(a,r,"trash-account",closed).Run();new SyncEngine(b,r,"trash-account",closed).Run();Assert(r.files.Count==count,"Deleted item resurrected/reuploaded");b.Trash(id,false);new SyncEngine(b,r,"trash-account",closed).Run();new SyncEngine(a,r,"trash-account",closed).Run();Assert(a.Library().Length==1&&!Store.IsDeleted(a.Read(id)),"Restoration failed");Assert(File.ReadAllText(a.DataFile(id,"source.pdf"))=="%PDF-original"&&r.blobs==1,"Trash changed/reuploaded original PDF");}
 static void TextEdits(){
 var doc=J.Parse("{\"version\":2,\"count\":1,\"pdf\":false,\"pages\":{\"0\":[{\"id\":\"11111111-1111-1111-1111-111111111111\",\"kind\":\"ink\",\"color\":-14271438,\"width\":2.0,\"marker\":false,\"points\":[[40.0,60,0.25],[80,100,1.2]]},{\"id\":\"22222222-2222-2222-2222-222222222222\",\"kind\":\"image\",\"asset\":\"33333333-3333-3333-3333-333333333333.png\",\"x\":10,\"y\":10,\"boxW\":40,\"boxH\":30,\"points\":[]}]}}");
 var original=J.Encode(J.Obj(doc["pages"])["0"]);var text=J.Parse("{\"id\":\"44444444-4444-4444-4444-444444444444\",\"kind\":\"text\",\"text\":\"Texto do PC\",\"color\":-14271438,\"fontSize\":20,\"x\":40,\"y\":150,\"boxW\":200,\"boxH\":25,\"points\":[]}");
 DesktopEdits.Apply(doc,new Dictionary<string,object>{{"op","append"},{"page",0},{"stroke",text}});var page=J.List(J.Obj(doc["pages"])["0"]).ToList();Assert(page.Count==3,"Text was not appended");DesktopEdits.Apply(doc,new Dictionary<string,object>{{"op","append"},{"page",0},{"stroke",text}});Assert(J.List(J.Obj(doc["pages"])["0"]).Count()==3,"Repeated append duplicated text");
 var edited=J.Parse(J.Encode(text));edited["text"]="Texto revisado";page[2]=edited;DesktopEdits.Apply(doc,new Dictionary<string,object>{{"op","page"},{"page",0},{"strokes",page}});Assert(J.S(J.Obj(J.List(J.Obj(doc["pages"])["0"]).Last()),"text")=="Texto revisado","Text edit failed");
 var restored=J.List(J.Parse("{\"page\":"+original+"}")["page"]).ToArray();DesktopEdits.Apply(doc,new Dictionary<string,object>{{"op","page"},{"page",0},{"strokes",restored}});Assert(J.Encode(J.Obj(doc["pages"])["0"])==original,"Deleting text modified tablet content");
 bool refused=false;try{DesktopEdits.Apply(doc,new Dictionary<string,object>{{"op","append"},{"page",0},{"stroke",J.Obj(restored[0])}});}catch{refused=true;}Assert(refused,"Windows bridge accepted a new drawing");
 refused=false;try{DesktopEdits.Apply(doc,new Dictionary<string,object>{{"op","page"},{"page",0},{"strokes",new object[]{restored[1]}}});}catch{refused=true;}Assert(refused,"Windows bridge erased tablet ink");
 var changed=J.Parse(J.Encode(J.Obj(restored[1])));changed["x"]=999;refused=false;try{DesktopEdits.Apply(doc,new Dictionary<string,object>{{"op","page"},{"page",0},{"strokes",new object[]{restored[0],changed}}});}catch{refused=true;}Assert(refused,"Windows bridge modified tablet image");
 }

}
